<style scoped lang="scss" src="./pagination-table.scss"></style>

<script>
import { Component, Prop, Vue } from 'vue-property-decorator';
import {
  TableCellAlignment,
  TableDataType,
  TableCellStatus,
  TableCellSize
} from '../../components/table/table.constants';
import TableCell from '../../components/table-cell/table-cell';
import TableHeaderCell from '../../components/table-header-cell/table-header-cell';
import { CurrencyNotation, CurrencyNotationValues } from '../constants';
import { has } from '../../util/has';
import TablePageIndicator from '../../components/table-page-indicator/table-page-indicator';
import Select from '../../components/select/select';
import SelectionMenu from '../../components/selection-menu/selection-menu';
import {
  TableHeaderCellAlignment,
  TableSortMode
} from '../table-header-cell/table-header-cell.constants';
import Button from '../../components/button/button';

const headerAlignToCellAlign = {
  [TableHeaderCellAlignment.LEFT]: TableCellAlignment.LEFT,
  [TableHeaderCellAlignment.CENTER]: TableCellAlignment.CENTER,
  [TableHeaderCellAlignment.RIGHT]: TableCellAlignment.RIGHT
};

const sizeToClass = {
  [TableCellSize.SMALL]: 'PaginationTable--small',
  [TableCellSize.MEDIUM]: 'PaginationTable--medium',
  [TableCellSize.LARGE]: 'PaginationTable--large'
};

const alignToClass = {
  [TableHeaderCellAlignment.LEFT]: 'PaginationTable--left',
  [TableHeaderCellAlignment.CENTER]: 'PaginationTable--center',
  [TableHeaderCellAlignment.RIGHT]: 'PaginationTable--right'
};

@Component({
  components: {
    TablePageIndicator,
    Select,
    SelectionMenu,
    TableHeaderCell,
    TableCell,
    Button
  }
})
export default class Table extends Vue {
  /**
   * Defines the columns of the table and sets their header information.
   *
   * {
   *   // Label for the header
   *   name: String,
   *   // Identifier used by row data to place a cell within the column
   *   id: String,
   *   // The data type of the column
   *   type: TableDataType,
   *   // Alignment of elements in the column
   *   align: TableHeaderCellAlignment,
   *   // The cell size of the column
   *   size: TableCellSize,
   *   // Rendering mode of the cells
   *   mode: TableCellMode,
   *   // Indicates if the column can be sorted or not. Defaults to true
   *   sortable: Boolean
   * },
   */
  @Prop({
    type: Array,
    default: () => []
  })
  headers;

  @Prop({
    type: Array,
    default: () => []
  })
  rows;

  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues)
  })
  currency;

  @Prop({
    type: Boolean,
    default: false
  })
  enableFilter;

  @Prop({
    type: String,
    default: ''
  })
  searchValue;

  @Prop({
    type: Number,
    default: 0
  })
  totalPageNumber;

  @Prop({
    type: Number,
    default: 0
  })
  currentPage;

  /**
   * The list of rows per page options.
   * Each option should include one label and its number value
   *
   * [
   *   {
   *     label: string;
   *     value: number;
   *   }
   * ]
   */
  @Prop({
    type: Array,
    default: () => []
  })
  rowsPerPageOptions;

  @Prop({
    type: Number,
    default: 10
  })
  defaultRowsPerPage;

  /**
   * Set this to true when you are loading stuff and you don't want the user
   * interacting with things or switching things.
   */
  @Prop({ type: Boolean, default: false })
  isLoading;

  @Prop({ type: Boolean, default: false })
  loadingNewData;

  @Prop({ type: [Boolean, String], default: '' })
  reportId;

  @Prop({ type: Boolean, default: false })
  multiFilter;

  @Prop({ type: Number, default: 10 })
  paginationLimit;

  isLoadingNewData = false;

  config = {};

  scrollLeft = 0;
  clientWidth = 0;
  scrollWidth = 0;
  showRightEdge = false;
  marginRight = 64;
  minWidth = 0;
  hovered = false;

  TableDataType = TableDataType;
  TableSortMode = TableSortMode;
  wasEnabledFilter = false;
  preReportId = '';
  init = true;

  beforeMount() {
    this.config = {
      sortId: undefined,
      sortMode: TableSortMode.NO_SORT,
      sortFunc: undefined,
      currentPage: 0,
      rowsPerPage: this.defaultRowsPerPage,
      filters: new Map()
    };

    for (let i = 0; i < this.headers.length; i++) {
      const header = this.headers[i];
      const filterOptions = header.filterOptions || [];

      if (filterOptions) {
        for (let j = 0; j < filterOptions.length; j++) {
          filterOptions[j].selected = true;
        }
      }

      this.config.filters.set(header.id, {
        searchWord: '',
        options: filterOptions
      });
    }
  }

  mounted() {
    window.addEventListener('resize', this.handleResize);
    window.addEventListener('scroll', this.handleScroll);

    for (let i = 0; i < this.headers.length; i++) {
      switch (this.headers[i].size) {
        case TableCellSize.SMALL:
          this.minWidth += 100;
          break;
        case TableCellSize.MEDIUM:
          this.minWidth += 120;
          break;
        case TableCellSize.LARGE:
          this.minWidth += 220;
          break;
        default:
          break;
      }
    }

    if (this.init) {
      /**/

      /**
       * Emits when the user request new data after filter or pagination.
       * @event request
       */
      // this.$emit("request", this.config);
      this.init = false;
    }

    this.checkRightEdge();
    this.isLoadingNewData = false;
  }

  beforeUpdate() {
    if (this.reportId !== this.preReportId) {
      if (this.preReportId !== '') {
        this.config.filters = new Map();
        this.config.sortId = undefined;
        this.config.sortMode = TableSortMode.NO_SORT;
        this.config.currentPage = 0;
        for (let i = 0; i < this.headers.length; i++) {
          const header = this.headers[i];
          const filterOptions = header.filterOptions || [];

          if (filterOptions) {
            for (let j = 0; j < filterOptions.length; j++) {
              filterOptions[j].selected = true;
            }
          }

          this.config.filters.set(header.id, {
            searchWord: '',
            options: filterOptions
          });
        }

        this.minWidth = 0;
        for (let i = 0; i < this.headers.length; i++) {
          switch (this.headers[i].size) {
            case TableCellSize.SMALL:
              this.minWidth += 100;
              break;
            case TableCellSize.MEDIUM:
              this.minWidth += 120;
              break;
            case TableCellSize.LARGE:
              this.minWidth += 220;
              break;
            default:
              break;
          }
        }
      }

      this.preReportId = this.reportId;
    }

    this.isLoadingNewData = this.loadingNewData;
  }

  updated() {
    if (this.wasEnabledFilter !== this.enableFilter) {
      this.wasEnabledFilter = this.enableFilter;
    }
    // this.isLoadingNewData = false;
  }

  checkRightEdge() {
    if (this.$refs.table) {
      this.scrollLeft = this.$refs.table.scrollLeft;
      this.clientWidth = this.$refs.table.clientWidth;
      this.scrollWidth = this.$refs.table.scrollWidth;

      this.showRightEdge =
        this.clientWidth < this.minWidth &&
        this.clientWidth + this.scrollLeft <= this.scrollWidth - 1;
    }
  }

  getCellAlignment(align) {
    return headerAlignToCellAlign[align];
  }

  getAlignClass(align) {
    return alignToClass[align];
  }

  getHeaderSizeClass(size) {
    if (this.rows && this.rows.length > 0) {
      return sizeToClass[size];
    }

    return `${sizeToClass[size]}Empty`;
  }

  getEmptySizeClass(size) {
    return `${sizeToClass[size]}Empty`;
  }

  get paddingStyle() {
    return {
      padding: `0px ${this.marginRight}px 0px 64px`
    };
  }

  get maskStyle() {
    return {
      opacity: this.hovered ? 0 : 1,
      left: `${this.scrollLeft}px`
    };
  }

  get upperStyle() {
    if (this.rows && this.rows.length > 0) {
      return {};
    }

    return {
      overflow: 'hidden'
    };
  }

  get currentRowsPerPage() {
    return this.config.rowsPerPage;
  }

  isWarning(row) {
    const status = row.data['status'];
    return row.warning || (status && status === TableCellStatus.FAILED);
  }

  get hasContent() {
    return (
      this.rows &&
      this.rows.length > 0 &&
      this.headers.filter(
        header => header.display === undefined || header.display === true
      ).length > 0
    );
  }

  getCellData(row, id) {
    return row.data[id];
  }

  getSearchDefaultValue(header) {
    const filter = this.config.filters.get(header.id);

    if (filter && filter.searchWord) {
      return filter.searchWord;
    }

    return '';
  }

  getFilterOptions(header) {
    const filter = this.config.filters.get(header.id);

    if (filter && filter.options && filter.options.length > 0) {
      return filter.options;
    }

    return [];
  }

  getSortOptions(header) {
    if (header) {
      return header.sortOptions;
    }

    return [];
  }

  getAllIsSelected(header) {
    const filter = this.config.filters.get(header.id);
    return (
      filter && filter.options.find(o => o.selected === false) === undefined
    );
  }

  get displayedHeaders() {
    return this.headers.filter(
      header => header.display === undefined || header.display === true
    );
  }

  focusOnId(id) {
    if (!this.multiFilter) {
      this.config.filters.forEach((filter, key) => {
        if (key !== id) {
          filter.options.forEach(option => {
            if (!option.selected) option.selected = true;
          });

          filter.searchWord = '';
        }
      });
    }
  }

  handleScroll() {
    this.checkRightEdge();
  }

  handleResize() {
    this.checkRightEdge();

    if (this.$refs.table) {
      if (this.minWidth < this.clientWidth + this.scrollLeft) {
        this.$refs.table.scrollLeft = Math.max(
          0,
          this.minWidth - this.clientWidth
        );
      }
    }

    if (this.$refs.tableContainer) {
      const containerWidth = this.$refs.tableContainer.clientWidth;

      this.marginRight = Math.min(
        Math.max(containerWidth - this.minWidth - 64, 0),
        64
      );
    }
  }

  handleSendMessage(index, id) {
    const i = this.currentPage * this.config.rowsPerPage + index;
    this.$emit('onSendMessage', i, id);
  }

  handleThankDonor(index, id) {
    const i = this.currentPage * this.config.rowsPerPage + index;
    if (this.rows[i].data[id].thanked !== undefined)
      this.rows[i].data[id].thanked = true;
    this.$emit('onThankDonor', i);
  }

  handlePageChange(index) {
    // Add handling logic to match UI disable logic
    if (index < 0) {
      return;
    }

    if (
      index > this.config.currentPage &&
      this.config.rowsPerPage > this.rows.length
    ) {
      return;
    }

    this.config.currentPage = index;
    /**
     * Emits when the user request new data after filter or pagination.
     * @event request
     */
    this.$emit('request', this.config);
  }

  handleSelectionChange(value) {
    if (value !== this.config.rowsPerPage) {
      this.config.rowsPerPage = value;
      this.config.currentPage = Math.min(
        this.totalPageNumber - 1,
        this.config.currentPage
      );
      /**
       * Emits when the user request new data after filter or pagination.
       * @event request
       */
      this.$emit('request', this.config);
    }
  }

  handleSortIncrease(header) {
    const id = header.id;
    this.focusOnId(id);
    this.config.sortId = id;
    this.config.sortMode = TableSortMode.ASCENDING;

    /**
     * Emits when the user request new data after filter or pagination.
     * @event request
     */
    this.$emit('request', this.config);
  }

  handleSortDecrease(header) {
    const id = header.id;
    this.config.sortId = id;
    this.config.sortMode = TableSortMode.DESCENDING;

    /**
     * Emits when the user request new data after filter or pagination.
     * @event request
     */
    this.$emit('request', this.config);
  }

  handleSearchInput(value, header) {
    if (header) {
      const filter = this.config.filters.get(header.id);

      if (filter) {
        if (value !== filter.searchWord) {
          filter.searchWord = value;
          /**
           * Emits when the user request new data after filter or pagination.
           * @event request
           */
          this.$emit('request', this.config, true);
        }

        /*if (value) {
          filter.searchWord = value;
        } else {
          filter.searchWord = "";
        }*/
      }
    }

    /*if (value !== this.config.filters[index].searchWord) {
      this.config.filters[index].searchWord = value;
    }*/
  }

  handleSelectOption(optionIndex, header) {
    if (header) {
      const filter = this.config.filters.get(header.id);
      this.focusOnId(header.id);
      if (filter) {
        const selected = filter.options[optionIndex].selected;
        filter.options[optionIndex].selected = !selected;
      }

      /**
       * Emits when the user request new data after filter or pagination.
       * @event request
       */
      this.$emit('request', this.config, true);
    }

    /*const selected = this.config.filters[headerIndex].options[optionIndex]
      .selected;
    this.config.filters[headerIndex].options[optionIndex].selected = !selected;*/
  }

  handleSelectAll(header) {
    const filter = this.config.filters.get(header.id);
    this.focusOnId(header.id);
    if (
      filter &&
      filter.options.find(option => option.selected === false) !== undefined
    ) {
      for (let i = 0; i < filter.options.length; i++) {
        filter.options[i].selected = true;
      }

      /**
       * Emits when the user request new data after filter or pagination.
       * @event request
       */
      this.$emit('request', this.config, true);
    }

    /*for (let i = 0; i < this.config.filters[index].options.length; i++) {
      this.config.filters[index].options[i].selected = true;
    }*/
  }

  handleClear(header) {
    const filter = this.config.filters.get(header.id);
    this.focusOnId(header.id);
    if (
      filter &&
      filter.options.find(option => option.selected === true) !== undefined
    ) {
      for (let i = 0; i < filter.options.length; i++) {
        filter.options[i].selected = false;
      }

      /**
       * Emits when the user request new data after filter or pagination.
       * @event request
       */
      this.$emit('request', this.config, true);
    }

    /*for (let i = 0; i < this.config.filters[index].options.length; i++) {
      this.config.filters[index].options[i].selected = false;
    }*/
  }

  handleSort(option, sortId) {
    this.config.sortId = sortId;
    this.config.sortMode = option.mode;
    this.config.sortFunc = option.compare;

    /**
     * Emits when the user request new data after filter or pagination.
     * @event request
     */
    this.$emit('request', this.config);
  }

  handleRowClicked(row) {
    /**
     * Emits when the user clicks a row in the report.
     * @event request
     */
    this.$emit('rowClicked', row);
  }

  handleMouseOver() {
    this.hovered = true;
  }

  handleMouseOut() {
    this.hovered = false;
  }
}
</script>

<template>
  <div class="PaginationTable" ref="tableContainer" :style="paddingStyle">
    <div
      class="PaginationTable__Upper"
      ref="table"
      @scroll="handleScroll"
      @mouseover="handleMouseOver"
      @mouseout="handleMouseOut"
      :style="upperStyle"
    >
      <div class="PaginationTable__Header">
        <TableHeaderCell
          v-for="(header, index) of displayedHeaders"
          :class="[
            'PaginationTable__HeaderCell',
            getHeaderSizeClass(header.size),
            getAlignClass(header.align)
          ]"
          :key="index"
          :name="header.name"
          :size="header.size"
          :align="header.align"
          :enableFilter="header.sortable && enableFilter"
          :filterOptions="getFilterOptions(header)"
          :sortOptions="getSortOptions(header)"
          :disable="!hasContent && !isLoading"
          :searchDefaultValue="getSearchDefaultValue(header)"
          :allIsSelected="getAllIsSelected(header)"
          @selectAll="handleSelectAll(header)"
          @clear="handleClear(header)"
          @selectOption="handleSelectOption($event, header)"
          @input="handleSearchInput($event, header)"
          @sort="handleSort($event, header.id)"
          @onSortIncrease="handleSortIncrease(header)"
          @onSortDecrease="handleSortDecrease(header)"
        />
      </div>
      <div v-if="isLoading" class="PaginationTable__LoaderContainer">
        <div class="PaginationTable__Loader" />
      </div>
      <div v-else>
        <div v-if="hasContent" class="PaginationTable__Content">
          <div class="PaginationTable__Rows" v-for="(row, i) of rows" :key="i">
            <div class="PaginationTable__Row" @click="$emit('rowClicked', row)">
              <TableCell
                :class="[
                  'PaginationTable__RowCell',
                  getHeaderSizeClass(header.size),
                  getAlignClass(header.align),
                  i % 2 === 1
                    ? 'PaginationTable--odd_row'
                    : 'PaginationTable--even_row'
                ]"
                v-for="(header, j) of displayedHeaders"
                :key="`${i}_${j}`"
                :type="header.type"
                :align="getCellAlignment(header.align)"
                :size="header.size"
                :mode="header.mode"
                :format="header.format"
                :data="getCellData(row, header.id)"
                :warning="isWarning(row)"
                :options="header.options"
                @onSendMessage="handleSendMessage(i, header.id)"
                @onThankDonor="handleThankDonor(i, header.id)"
              />
            </div>
          </div>
        </div>
        <div v-if="hasContent" class="PaginationTable__Mask" :style="maskStyle">
          <transition name="fade">
            <div v-if="showRightEdge" class="PaginationTable__RightEdge" />
          </transition>
        </div>
      </div>
    </div>
    <div
      v-if="!hasContent && !isLoading"
      class="PaginationTable__EmptyContainer"
    >
      <div class="PaginationTable__Empty">
        <div v-for="i in 11" :key="i" class="PaginationTable__EmptyRow">
          <div
            v-for="(header, index) of headers"
            :key="index"
            :class="[
              'PaginationTable__EmptyCell',
              getEmptySizeClass(header.size)
            ]"
          >
            <div class="PaginationTable__EmptyFill" />
          </div>
        </div>
      </div>
      <div class="PaginationTable__EmptyMask">
        <div class="PaginationTable__MainTitle">
          Your reporting query returned no results. Try modifying your filters.
        </div>
        <div class="PaginationTable__SubTitle">
          Your reports will populate once there is campaign activity.
        </div>
      </div>
    </div>
    <div
      v-if="hasContent && !isLoadingNewData"
      class="PaginationTable__Controls"
    >
      <div class="PaginationTable__ControlLeft">
        <div>Show</div>
        <div class="PaginationTable__Perpage">
          <Select
            class="RowsPerPageMenu"
            label="# Rows"
            :value="currentRowsPerPage"
            :items="rowsPerPageOptions"
            @select="handleSelectionChange"
          />
        </div>
        <div>per page</div>
      </div>
      <div v-if="totalPageNumber > 1" class="PaginationTable__ControlMiddle">
        <TablePageIndicator
          :totalPageNumber="totalPageNumber"
          :startPage="currentPage"
          :displayNumber="paginationLimit"
          :receiveOnly="true"
          @onChangePage="handlePageChange"
        />
      </div>
      <div
        v-else-if="totalPageNumber == 0"
        class="PaginationTable__ControlMiddle"
      >
        <div class="TablePageIndicator">
          <div
            :class="[
              'TablePageIndicator__Button',
              currentPage === 0
                ? 'TablePageIndicator--unclickable'
                : 'TablePageIndicator--clickable'
            ]"
            @click="handlePageChange(currentPage - 1)"
          >
            ← Previous
          </div>
          <div
            :class="[
              'TablePageIndicator__Button',
              config.rowsPerPage > rows.length
                ? 'TablePageIndicator--unclickable'
                : 'TablePageIndicator--clickable'
            ]"
            @click="handlePageChange(currentPage + 1)"
          >
            Next →
          </div>
        </div>
      </div>
      <div class="PaginationTable__ControlRight" v-if="totalPageNumber > 1">
        {{ `Page ${this.currentPage + 1} of ${totalPageNumber}` }}
      </div>
    </div>
  </div>
</template>
